package org.mockito.internal.invocation;

import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.realmethod.RealMethod;
import org.mockito.internal.matchers.*;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import org.mockito.internal.util.*;
import org.mockito.invocation.InvocationOnMock;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class Invocation_callRealMethod_TriageGen2Test {

    /**
     * Test that callRealMethod successfully invokes the real method on the mock object
     * and returns the expected value.
     */
    @Test
    public void testCallRealMethod_Success() throws Throwable {
        // Setup dependencies
        TestTarget target = new TestTarget();
        Method realMethod = TestTarget.class.getMethod("sayHello", String.class);
        Object mockInstance = new Object();
        Object[] rawArguments = new Object[]{"World"};

        // MockitoMethod is an interface/abstract concept in Mockito internals, 
        // but for a unit test of this specific method, we need a valid implementation
        // or a mock of it. Since it's internal, we mock it.
        MockitoMethod mockitoMethod = mock(MockitoMethod.class);

        // Create the Invocation instance using the constructor provided in the prompt
        // Note: In a real environment, this constructor is package-private or internal.
        Invocation invocation = new Invocation(
                mockInstance,
                mockitoMethod,
                rawArguments,
                1,
                realMethod
        );

        // Execute
        Object result = invocation.callRealMethod();

        // Verify
        assertEquals("Hello World", result);
    }

    /**
     * Test that callRealMethod propagates exceptions thrown by the real method.
     */
    @Test(expected = RuntimeException.class)
    public void testCallRealMethod_ThrowsException() throws Throwable {
        TestTarget target = new TestTarget();
        Method realMethod = TestTarget.class.getMethod("throwException");
        Object mockInstance = new Object();
        Object[] rawArguments = new Object[0];
        MockitoMethod mockitoMethod = mock(MockitoMethod.class);

        Invocation invocation = new Invocation(
                mockInstance,
                mockitoMethod,
                rawArguments,
                1,
                realMethod
        );

        // Execute
        invocation.callRealMethod();
    }

    /**
     * Test that callRealMethod works with void methods.
     */
    @Test
    public void testCallRealMethod_VoidMethod() throws Throwable {
        TestTarget target = new TestTarget();
        Method realMethod = TestTarget.class.getMethod("voidMethod");
        Object mockInstance = new Object();
        Object[] rawArguments = new Object[0];
        MockitoMethod mockitoMethod = mock(MockitoMethod.class);

        Invocation invocation = new Invocation(
                mockInstance,
                mockitoMethod,
                rawArguments,
                1,
                realMethod
        );

        // Execute
        Object result = invocation.callRealMethod();

        // Verify
        assertEquals(null, result);
    }

    /**
     * Helper class to provide real methods for invocation testing.
     */
    public static class TestTarget {
        public String sayHello(String name) {
            return "Hello " + name;
        }

        public void throwException() {
            throw new RuntimeException("Intentional Exception");
        }

        public void voidMethod() {
            // Do nothing
        }
    }
}
